'use strict';
(async()=>{const $=s=>document.querySelector(s),esc=Atlas.esc;let profiles=[];const profilePage=location.pathname.endsWith('/character.html');const params=new URLSearchParams(location.search),recordURL=(table,id)=>`index.html?table=${table}&record=${id}#${table}`;
function state(id){if(profilePage){history.replaceState(null,'','?id='+encodeURIComponent(id));return}const p=new URLSearchParams({q:$('#directory-query').value,status:$('#identity-status').value});if(id)p.set('id',id);history.replaceState(null,'','?'+p)}
const normalize=s=>String(s||'').toLowerCase().replace(/[_\s-]+/g,' ').trim();
const identity=p=>p.status==='Confirmed'?'Confirmed name':p.status==='Unmapped'?'Internal name only':'Name match · unconfirmed';
function filter(){const q=normalize($('#directory-query').value),status=$('#identity-status').value,rows=profiles.filter(p=>(!status||p.status===status)&&[p.name,p.internal,...p.variants.map(r=>r.fields.Name)].map(normalize).join(' ').includes(q));$('#directory-status').textContent=`${rows.length} characters · ${profiles.filter(p=>p.name).length} names mapped / ${profiles.length} profiles`;$('#directory').innerHTML=rows.map(p=>`<a class="card" href="character.html?id=${p.id}">${p.image?`<img loading="lazy" src="data/visual/${esc(p.image)}" alt="${esc(p.name||p.internal)}">`:'<div class="placeholder">No portrait linked</div>'}<span class="info"><strong>${esc(p.name||p.internal)}</strong><small>Internal: ${esc(p.internal)}</small><small class="identity-label">${esc(identity(p))} · ${p.variants.length} variants</small></span></a>`).join('')||'<p>No names match these filters.</p>';state(new URLSearchParams(location.search).get('id'))}
function show(id,scroll=true){const p=profiles.find(p=>String(p.id)===String(id));if(!p){$('#profile').hidden=false;$('#profile').textContent='This character profile was not found.';return}state(p.id);document.title=(p.name||p.internal)+' · Character profile';$('#profile').hidden=false;const base=p.variants.find(r=>r.id===p.id)||p.variants[0];$('#profile').innerHTML=`<div class="profile-heading">${p.image?`<img src="data/visual/${esc(p.image)}" alt="${esc(p.name||p.internal)}">`:''}<div><p class="eyebrow">CHARACTER PROFILE · #${p.id}</p><h1>${esc(p.name||p.internal)}</h1><p>Internal: ${esc(p.internal)} · ${esc(identity(p))}</p></div></div><details class="identity-evidence"><summary>How this name was identified · ${esc(p.status)}</summary><p>${esc(p.evidence||'No verified in-game name is linked yet.')}</p></details><p class="notice">Values below come from the stored game data and may differ from final in-game stats.</p><div class="profile-actions"><button id="save-character">☆ Save character</button><a href="visual.html?related=heroes:${base.id}">Browse artwork ↗</a><a href="${recordURL('heroes',base.id)}">Open source record ↗</a></div><div class="profile-columns"><div><article class="profile-box"><h3>Evolution & variants</h3><p>Explore the stored forms of this character. Open a variant for its full data or add it to a comparison.</p><table class="profile-table"><thead><tr><th>Variant</th><th>Element</th><th>Health</th><th>Defense</th><th></th></tr></thead><tbody>${p.variants.map(r=>`<tr><td><a href="${recordURL('heroes',r.id)}">${esc(r.fields.Name||r.id)}</a></td><td>${esc(r.fields.ElementalType||'—')}</td><td>${Number(r.fields.Hp||0).toLocaleString()}</td><td>${Number(r.fields.Def||0).toLocaleString()}</td><td><button data-compare="${r.id}">Compare</button></td></tr>`).join('')}</tbody></table><details><summary>Technical details: ranks and evolution links</summary><pre>${esc(JSON.stringify(p.variants.map(r=>({id:r.id,name:r.fields.Name,rankCode:r.fields.Rank,nextEvolution:r.fields.EvolveTo,origin:r.fields.OriginId})),null,2))}</pre></details></article><article class="profile-box"><h3>Weapons</h3><p>Exclusive weapons and starting equipment linked in the game data.</p><div class="grid">${p.weapons.map(w=>`<a class="card" href="${recordURL('static-items',w.id)}">${w.image?`<img loading="lazy" src="data/visual/${esc(w.image)}" alt="${esc(w.name)}">`:''}<span class="info"><strong>${esc(w.name)}</strong><small>${w.exclusive?'Exclusive weapon':'Default weapon'}</small></span></a>`).join('')||'<p>No explicit weapon link recovered.</p>'}</div></article></div><div><article class="profile-box"><h3>Biography & profile</h3>${p.profile?`<dl>${['Age','Height','Weight','Tribe'].filter(k=>p.profile[k]).map(k=>`<dt>${esc(k)}</dt><dd>${esc(p.profile[k].map(v=>typeof v==='string'?v.replace(/^profile_tribe_/,'').replaceAll('_',' '):v).join(', '))}</dd>`).join('')}</dl>`:''}${p.biography?`<p>${esc(p.biography)}</p><small>${esc(p.biographyNote)} <a href="${recordURL('text',p.biographyId)}">English text #${p.biographyId}</a></small>`:`<p>A readable English biography has not been linked with enough confidence.</p>${p.profile?`<small>Stored story key: ${esc(p.profile.Story)}</small>`:''}`}</article><article class="profile-box"><h3>Skills & battle actions</h3><p>Attack steps and abilities associated with this character. Internal action names are shown where no in-game label has been linked.</p><ul>${p.skills.map(s=>`<li><a href="${recordURL('actions',s.record)}">${esc(s.name)}</a></li>`).join('')||'<li>No action records resolved for this class.</li>'}</ul><details><summary>Battle-style source details</summary><pre>${esc(JSON.stringify(p.battleStyles,null,2))}</pre></details></article></div></div>`;$('#save-character').onclick=()=>Atlas.save(p.name||p.internal,'character.html?id='+p.id);$('#profile').querySelectorAll('[data-compare]').forEach(b=>b.onclick=()=>{const r=p.variants.find(r=>String(r.id)===b.dataset.compare);Atlas.addCompare('heroes',r.id,r.fields.Name)});if(scroll)$('#profile').scrollIntoView({behavior:'smooth',block:'start'})}
try{const r=await fetch('data/characters.json.gz');if(!r.ok)throw Error('Character data unavailable');profiles=await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).json();if(profilePage){show(params.get('id'),false);return}if(params.has('id')){location.replace('character.html?id='+encodeURIComponent(params.get('id')));return}$('#directory-query').value=params.get('q')||'';$('#identity-status').value=params.get('status')||'';filter();if(params.get('id'))show(params.get('id'));$('#directory-query').oninput=filter;$('#identity-status').onchange=filter;$('#directory').onclick=e=>{const b=e.target.closest('[data-profile]');if(b)show(b.dataset.profile)}}catch(e){$(profilePage?'#profile':'#directory-status').textContent=e.message}
})();
